(function(){'use strict';var root=document.querySelector('[data-pay]');if(!root)return;var msg=root.querySelector('.pay-msg');var note=root.querySelector('[data-cur-note]');var NOTES={inr:'Pay with UPI, cards, net banking or wallets.',usd:'Pay with any international Visa, Mastercard or Amex card.'};var cur='inr';function setCur(c){cur=c==='usd'?'usd':'inr';root.querySelectorAll('[data-cur]').forEach(function(b){b.setAttribute('aria-checked',b.getAttribute('data-cur')===cur?'true':'false');});root.querySelectorAll('.plan-amount').forEach(function(el){el.textContent=el.getAttribute('data-'+cur);});root.querySelectorAll('.plan-alt').forEach(function(el){el.textContent=el.getAttribute('data-alt-'+cur);});if(note)note.textContent=NOTES[cur];try{localStorage.setItem('vs-cur',cur);}catch(e){}
root.querySelectorAll('.plan-was').forEach(function(w){w.remove();});if(window.__vsRequote)window.__vsRequote();}
var saved=null;try{saved=localStorage.getItem('vs-cur');}catch(e){}
if(!saved){var tz='';try{tz=Intl.DateTimeFormat().resolvedOptions().timeZone||'';}catch(e){}
saved=/^Asia\/(Kolkata|Calcutta)$/.test(tz)?'inr':'usd';}
setCur(saved);root.querySelectorAll('[data-plan-pick]').forEach(function(sel){var card=sel.closest('[data-plan-card]');sel.addEventListener('change',function(){var o=sel.options[sel.selectedIndex];var amt=card.querySelector('.plan-amount');amt.setAttribute('data-inr',o.getAttribute('data-inr'));amt.setAttribute('data-usd',o.getAttribute('data-usd'));card.querySelector('.plan-blurb').textContent=o.getAttribute('data-blurb');var b=card.querySelector('[data-buy]');if(b)b.setAttribute('data-buy',sel.value);var t=card.querySelector('[data-plan-track]');if(t)t.value=o.getAttribute('data-track');var n=card.querySelector('input[name=_vsnonce]');if(n&&o.getAttribute('data-wl-nonce'))n.value=o.getAttribute('data-wl-nonce');setCur(cur);if(window.__vsRequote)window.__vsRequote();});});root.querySelectorAll('[data-cur]').forEach(function(b){b.addEventListener('click',function(){setCur(b.getAttribute('data-cur'));});b.addEventListener('keydown',function(e){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){setCur(cur==='inr'?'usd':'inr');root.querySelector('[data-cur="'+cur+'"]').focus();}});});if(root.getAttribute('data-action')!=='buy')return;var api=root.getAttribute('data-api');var nonce=root.getAttribute('data-nonce');function say(text,ok){msg.hidden=!text;msg.textContent=text||'';msg.className='pay-msg notice '+(ok?'notice-success':'notice-error');if(text)msg.scrollIntoView({block:'nearest',behavior:'smooth'});}
function post(path,data){return fetch(api+path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-WP-Nonce':nonce},body:JSON.stringify(data)}).then(function(r){return r.json().catch(function(){return{};}).then(function(j){if(!r.ok)throw new Error(j&&j.message?j.message:'Something went wrong. Please try again.');return j;});});}
var coupon='',okFor={};var cInput=root.querySelector('[data-coupon]'),cMsg=root.querySelector('.pay-coupon-msg');function requote(){if(!coupon)return;var names=[];okFor={};var jobs=Array.prototype.map.call(root.querySelectorAll('[data-buy]'),function(b){var plan=b.getAttribute('data-buy'),card=b.closest('[data-plan-card]');return post('quote',{plan:plan,currency:cur,coupon:coupon}).then(function(q){okFor[plan]=true;var amt=card.querySelector('.plan-amount');var was=card.querySelector('.plan-was');if(!was){was=document.createElement('s');was.className='plan-was';amt.parentNode.insertBefore(was,amt);}
was.textContent=amt.getAttribute('data-'+cur);amt.textContent=q.label;names.push(card.querySelector('h2').textContent);}).catch(function(){});});Promise.all(jobs).then(function(){if(cMsg)cMsg.textContent=names.length?'✅ '+coupon+' applied to: '+names.join(', '):'❌ That coupon is not valid for these plans, or has expired.';});}
window.__vsRequote=requote;var cApply=root.querySelector('[data-coupon-apply]');if(cApply){cApply.addEventListener('click',function(){coupon=(cInput.value||'').toUpperCase().replace(/[^A-Z0-9_-]/g,'');cInput.value=coupon;root.querySelectorAll('.plan-was').forEach(function(w){w.remove();});root.querySelectorAll('.plan-amount').forEach(function(a){a.textContent=a.getAttribute('data-'+cur);});if(!coupon){okFor={};if(cMsg)cMsg.textContent='';return;}
requote();});cInput.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();cApply.click();}});}
var sdk=null;function loadCheckout(){if(window.Razorpay)return Promise.resolve();if(sdk)return sdk;sdk=new Promise(function(resolve,reject){var s=document.createElement('script');s.src='https://checkout.razorpay.com/v1/checkout.js';s.async=true;s.onload=resolve;s.onerror=function(){sdk=null;reject(new Error('Could not load the payment window. Check your connection and try again.'));};document.head.appendChild(s);});return sdk;}
root.querySelectorAll('[data-buy]').forEach(function(btn){var label=btn.textContent;function busy(on,text){btn.disabled=on;btn.textContent=on?text:label;}
btn.addEventListener('click',function(){say('');busy(true,'Opening secure checkout…');var plan=btn.getAttribute('data-buy');post('order',{plan:plan,currency:cur,coupon:okFor[plan]?coupon:''}).then(function(o){if(o.demo){practice(o,busy);return;}
return loadCheckout().then(function(){openRazorpay(o,busy);});}).catch(function(e){busy(false);say(e.message);});});});function finishPaid(v){say('Payment received 🎉 Taking you to your course…',true);window.location.href=v.redirect;}
function practice(o,busy){var d=document.createElement('div');d.className='pay-demo';d.setAttribute('role','dialog');d.setAttribute('aria-modal','true');d.setAttribute('aria-label','Practice checkout');d.innerHTML='<div class="pay-demo-box"><p class="pay-demo-tag">🧪 Practice checkout · no real money</p>'+'<p class="pay-demo-plan"></p><p class="pay-demo-amount"></p>'+'<div class="pay-demo-methods"><span>UPI</span><span>Card</span><span>Net banking</span><span>Wallet</span></div>'+'<button type="button" class="btn btn-primary btn-block" data-r="success">✅ Pay (practice)</button>'+'<button type="button" class="btn btn-ghost btn-block" data-r="failed">❌ Make it fail</button>'+'<button type="button" class="btn-link" data-r="cancel">Cancel</button>'+'<p class="pay-demo-note">Real readers see Razorpay\'s window here (UPI, cards, net banking).</p></div>';d.querySelector('.pay-demo-plan').textContent=o.description;d.querySelector('.pay-demo-amount').textContent=o.label+' '+o.currency;document.body.appendChild(d);var first=d.querySelector('[data-r=success]');first.focus();function close(){d.remove();document.removeEventListener('keydown',esc);}
function esc(e){if(e.key==='Escape'){close();busy(false);}}
document.addEventListener('keydown',esc);d.addEventListener('click',function(e){var r=e.target.getAttribute&&e.target.getAttribute('data-r');if(!r)return;close();if(r==='cancel'){busy(false);return;}
busy(true,'Confirming payment…');post('verify',{razorpay_order_id:o.order_id,demo_result:r}).then(finishPaid).catch(function(err){busy(false);say(err.message);});});}
function openRazorpay(o,busy){var rzp=new window.Razorpay({key:o.key,order_id:o.order_id,amount:o.amount,currency:o.currency,name:o.name,description:o.description,prefill:o.prefill,theme:{color:'#0a7d4f'},modal:{ondismiss:function(){busy(false);}},handler:function(reply){busy(true,'Confirming payment…');post('verify',reply).then(finishPaid).catch(function(e){busy(false);say(e.message);});}});rzp.on('payment.failed',function(r){busy(false);say((r&&r.error&&r.error.description?r.error.description+' ':'')+'The payment did not go through. If money was deducted, your bank returns it automatically. Please try again or use another method.');});rzp.open();}})();